function parseResponse<T>(
  text: string,
  shape: ResponseShape,
  decode: (value: unknown) => T,
): ResponseEnvelope<T> {
  const value = parseStrictJSON(text);
  const unknown: Record<string, string> = {};
  const known = stripResponseUnknown(text, value, shape, "", unknown);
  return Object.freeze({ value: decode(known), unknown: Object.freeze(unknown) });
}
export function encodeResponse<T>(envelope: ResponseEnvelope<T>): string {
  const entries = Object.entries(envelope.unknown)
    .map(([pointer, raw]) => ({ pointer, raw, segments: splitJSONPointer(pointer) }))
    .toSorted((left, right) =>
      left.pointer < right.pointer ? -1 : left.pointer > right.pointer ? 1 : 0,
    );
  for (let index = 0; index < entries.length; index++) {
    parseStrictJSON(entries[index]!.raw);
    for (let previous = 0; previous < index; previous++)
      if (
        jsonPointerPrefix(entries[previous]!.segments, entries[index]!.segments) ||
        jsonPointerPrefix(entries[index]!.segments, entries[previous]!.segments)
      )
        error("SIDECAR_POINTER_OVERLAP", entries[index]!.pointer);
  }
  let encoded = JSON.stringify(envelope.value);
  for (const entry of entries)
    encoded = mergeSidecarRaw(encoded, entry.segments, entry.raw, entry.pointer);
  return encoded;
}

export function parseProblem(text: string): Problem {
  const source = strictRecord(
    parseStrictJSON(text),
    ["type", "title", "status", "error", "requestId"],
    ["type", "title", "status", "error", "requestId"],
  );
  const stable = strictRecord(
    source.error,
    ["code", "retryable", "retryAfterSeconds"],
    ["code", "retryable"],
    "/error",
  );
  const code = boundedString(stable.code, 3, 96, "/error/code");
  if (!/^[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)*$/u.test(code))
    error("INVALID_STABLE_ERROR_CODE", "/error/code");
  if (typeof stable.retryable !== "boolean") error("INVALID_FIELD_TYPE", "/error/retryable");
  const retryable = stable.retryable as boolean;
  const base = {
    type: absoluteURI(source.type, "/type"),
    title: boundedString(source.title, 1, 160, "/title"),
    status: integer(source.status, 400, 599, "/status"),
    error: { code, retryable },
    requestId: identifier(source.requestId, "/requestId"),
  };
  if (stable.retryAfterSeconds !== undefined)
    return Object.freeze({
      ...base,
      error: Object.freeze({
        ...base.error,
        retryAfterSeconds: integer(stable.retryAfterSeconds, 0, 86400, "/error/retryAfterSeconds"),
      }),
    });
  return Object.freeze({ ...base, error: Object.freeze(base.error) });
}
